    /** 0000-MAINLINE-CONTROL */
    private void p0000MainlineControl() {
        cocoonPerform(1, 2);   // PERFORM 0100-INITIAL-ROUTINE THRU 0100-EXIT
        cocoonPerform(3, 4);   // PERFORM 1000-EDIT-INPUT-DATA THRU 1000-EXIT
        if (ppsRtc.value().compareTo("00") == 0) {
            cocoonPerform(7, 8);   // PERFORM 1700-EDIT-DRG-CODE THRU 1700-EXIT
        }
        if (ppsRtc.value().compareTo("00") == 0) {
            cocoonPerform(11, 12);   // PERFORM 1800-EDIT-IPPS-DRG-CODE THRU 1800-EXIT
        }
        if (ppsRtc.value().compareTo("00") == 0) {
            cocoonPerform(13, 14);   // PERFORM 2000-ASSEMBLE-PPS-VARIABLES THRU 2000-EXIT
        }
        if (ppsRtc.value().compareTo("00") == 0) {
            cocoonPerform(15, 16);   // PERFORM 3000-CALC-PAYMENT THRU 3000-EXIT
        }
        if (!((ppsRtc.value().compareTo("50") >= 0 && ppsRtc.value().compareTo("99") <= 0)) && !(ppsRtc1.value().compareTo("D") == 0)) {
            cocoonPerform(31, 32);   // PERFORM 6000-CALC-HIGH-COST-OUTLIER THRU 6000-EXIT
        }
        if (!((ppsRtc.value().compareTo("50") >= 0 && ppsRtc.value().compareTo("99") <= 0)) && !(ppsRtc1.value().compareTo("D") == 0)) {
            cocoonPerform(35, 36);   // PERFORM 7000-SET-FINAL-RETURN-CODES THRU 7000-EXIT
        }
        if (!((ppsRtc.value().compareTo("50") >= 0 && ppsRtc.value().compareTo("99") <= 0)) && !(ppsRtc1.value().compareTo("D") == 0)) {
            cocoonPerform(43, 44);   // PERFORM 8000-CALC-FINAL-PMT THRU 8000-EXIT
        }
        cocoonPerform(45, 46);   // PERFORM 9000-MOVE-RESULTS THRU 9000-EXIT
        cocoonStop();   // GOBACK
    }

