    /** 7200-SET-NEW-RETURN-CODES */
    private void p7200SetNewReturnCodes() {
        ppsRtc1.store(" ");
        ppsRtc2.store(" ");
        ppsRtc1.store("C");
        cocoonPerform(41, 42);   // PERFORM 7250-SEARCH-FOR-VENT-PROC THRU 7250-EXIT
        if (wsVentStatus.value().compareTo("Y") == 0) {
            ppsRtc1.store("B");
        }
        if ((ppsSubmDrgCode.value().compareTo("876") == 0 || ppsSubmDrgCode.value().compareTo("880") == 0 || ppsSubmDrgCode.value().compareTo("881") == 0 || ppsSubmDrgCode.value().compareTo("882") == 0 || ppsSubmDrgCode.value().compareTo("883") == 0 || ppsSubmDrgCode.value().compareTo("884") == 0 || ppsSubmDrgCode.value().compareTo("885") == 0 || ppsSubmDrgCode.value().compareTo("887") == 0 || ppsSubmDrgCode.value().compareTo("886") == 0 || ppsSubmDrgCode.value().compareTo("894") == 0 || ppsSubmDrgCode.value().compareTo("895") == 0 || ppsSubmDrgCode.value().compareTo("896") == 0 || ppsSubmDrgCode.value().compareTo("897") == 0 || ppsSubmDrgCode.value().compareTo("945") == 0 || ppsSubmDrgCode.value().compareTo("946") == 0) && (wsPrimaryPmtType.value().compareTo("3") == 0 || wsPrimaryPmtType.value().compareTo("4") == 0)) {
            ppsRtc1.store("A");
        }
        if (wsPrimaryPmtType.value().compareTo("4") == 0 && wsSecondaryPmtTypeSnt.value().compareTo("1") == 0) {
            if (ppsOutlierPayAmt.value().compareTo(new BigDecimal("0")) == 0 && wsSecondaryPmtTypeStd.value().compareTo("1") == 0) {
                ppsRtc2.store("0");
            }
            if (ppsOutlierPayAmt.value().compareTo(new BigDecimal("0")) > 0 && wsSecondaryPmtTypeStd.value().compareTo("1") == 0) {
                ppsRtc2.store("1");
            }
            if (ppsOutlierPayAmt.value().compareTo(new BigDecimal("0")) == 0 && wsSecondaryPmtTypeStd.value().compareTo("2") == 0) {
                ppsRtc2.store("2");
            }
            if (ppsOutlierPayAmt.value().compareTo(new BigDecimal("0")) > 0 && wsSecondaryPmtTypeStd.value().compareTo("2") == 0) {
                ppsRtc2.store("3");
            }
        }
        if (wsPrimaryPmtType.value().compareTo("4") == 0 && wsSecondaryPmtTypeSnt.value().compareTo("2") == 0) {
            if (ppsOutlierPayAmt.value().compareTo(new BigDecimal("0")) == 0 && wsSecondaryPmtTypeStd.value().compareTo("1") == 0) {
                ppsRtc2.store("4");
            }
            if (ppsOutlierPayAmt.value().compareTo(new BigDecimal("0")) > 0 && wsSecondaryPmtTypeStd.value().compareTo("1") == 0) {
                ppsRtc2.store("5");
            }
            if (ppsOutlierPayAmt.value().compareTo(new BigDecimal("0")) == 0 && wsSecondaryPmtTypeStd.value().compareTo("2") == 0) {
                ppsRtc2.store("6");
            }
            if (ppsOutlierPayAmt.value().compareTo(new BigDecimal("0")) > 0 && wsSecondaryPmtTypeStd.value().compareTo("2") == 0) {
                ppsRtc2.store("7");
            }
        }
        if (wsPrimaryPmtType.value().compareTo("3") == 0) {
            if (wsSecondaryPmtTypeSnt.value().compareTo("1") == 0) {
                ppsRtc2.store("A");
            }
            if (wsSecondaryPmtTypeSnt.value().compareTo("2") == 0) {
                if (ppsOutlierPayAmt.value().compareTo(new BigDecimal("0")) == 0) {
                    ppsRtc2.store("B");
                } else {
                    ppsRtc2.store("C");
                }
            }
        }
        if (wsPrimaryPmtType.value().compareTo("2") == 0) {
            if (wsSecondaryPmtTypeStd.value().compareTo("2") == 0 && ppsOutlierPayAmt.value().compareTo(new BigDecimal("0")) == 0) {
                ppsRtc2.store("D");
            }
            if (wsSecondaryPmtTypeStd.value().compareTo("2") == 0 && ppsOutlierPayAmt.value().compareTo(new BigDecimal("0")) > 0) {
                ppsRtc2.store("E");
            }
            if (wsSecondaryPmtTypeStd.value().compareTo("1") == 0 && ppsOutlierPayAmt.value().compareTo(new BigDecimal("0")) == 0) {
                ppsRtc2.store("F");
            }
            if (wsSecondaryPmtTypeStd.value().compareTo("1") == 0 && ppsOutlierPayAmt.value().compareTo(new BigDecimal("0")) > 0) {
                ppsRtc2.store("G");
            }
        }
    }

