    /** 7250-SEARCH-FOR-VENT-PROC */
    private void p7250SearchForVentProc() {
        idxProc = 1;   // SET IDX-PROC TO 1
        while (true) {   // SEARCH B-PROCEDURE-CODE
            if (idxProc > 25) {
                wsVentStatus.store("N");  // SET VENT-NOT-PRESENT TO TRUE
                break;
            }
            if (ventIcd10Code.value().compareTo(bProcedureCode[idxProc - 1].value()) == 0) {
                wsVentStatus.store("Y");  // SET VENT-PRESENT TO TRUE
                cocoonGoTo(42);   // GO TO 7250-EXIT
                break;
            }
            idxProc++;
        }
    }

