    /** 8000-CALC-FINAL-PMT */
    private void p8000CalcFinalPmt() {
        if (wsPrimaryPmtType.value().compareTo("1") == 0) {
            ppsFinalPayAmt.store(ppsDrgAdjPayAmt.value().add(ppsOutlierPayAmt.value()));
        }
        if (!(wsPrimaryPmtType.value().compareTo("1") == 0)) {
            if (wsPrimaryPmtType.value().compareTo("3") == 0) {
                ppsSiteNeutralCostPmt.storeRounded(ppsSiteNeutralCostPmt.value().multiply(hBdgtNeutFactor.value()));
                // TRUNCATES: the expression produces up to 8 integer digits and PPS-SITE-NEUTRAL-COST-PMT holds 7. The high-order digits are lost, as in the original.
                ppsSiteNeutralIppsPmt.storeRounded(ppsSiteNeutralIppsPmt.value().multiply(hBdgtNeutFactor.value()).multiply(hSiteNeutralIppsAdj.value()));
                // TRUNCATES: the expression produces up to 9 integer digits and PPS-SITE-NEUTRAL-IPPS-PMT holds 7. The high-order digits are lost, as in the original.
                ppsOutlierPayAmt.storeRounded(ppsOutlierPayAmt.value().multiply(hSiteNeutralIppsAdj.value()));
                // TRUNCATES: the expression produces up to 8 integer digits and PPS-OUTLIER-PAY-AMT holds 7. The high-order digits are lost, as in the original.
            }
            if (wsPrimaryPmtType.value().compareTo("4") == 0) {
                ppsSiteNeutralCostPmt.storeRounded(ppsSiteNeutralCostPmt.value().multiply(hBdgtNeutFactor.value()).multiply(hBlendSnt.value()));
                // TRUNCATES: the expression produces up to 9 integer digits and PPS-SITE-NEUTRAL-COST-PMT holds 7. The high-order digits are lost, as in the original.
                ppsSiteNeutralIppsPmt.storeRounded(ppsSiteNeutralIppsPmt.value().multiply(hBdgtNeutFactor.value()).multiply(hSiteNeutralIppsAdj.value()).multiply(hBlendSnt.value()));
                // TRUNCATES: the expression produces up to 10 integer digits and PPS-SITE-NEUTRAL-IPPS-PMT holds 7. The high-order digits are lost, as in the original.
                ppsStandardFullPmt.storeRounded(ppsStandardFullPmt.value().multiply(hBlendStd.value()));
                // TRUNCATES: the expression produces up to 8 integer digits and PPS-STANDARD-FULL-PMT holds 7. The high-order digits are lost, as in the original.
                ppsStandardSsoPmt.storeRounded(ppsStandardSsoPmt.value().multiply(hBlendStd.value()));
                // TRUNCATES: the expression produces up to 8 integer digits and PPS-STANDARD-SSO-PMT holds 7. The high-order digits are lost, as in the original.
            }
            ppsFinalPayAmt.store(ppsStandardFullPmt.value().add(ppsStandardSsoPmt.value()).add(ppsSiteNeutralCostPmt.value()).add(ppsSiteNeutralIppsPmt.value()).add(ppsOutlierPayAmt.value()));
            hPreDppPay.store(ppsFinalPayAmt.value());
            if (bLtchDppIndicatorSw.value().compareTo("Y") == 0) {
                cocoonPerform(25, 26);   // PERFORM 3500-CALC-IPPS-LIKE-AMT THRU 3500-EXIT
                ppsLtchDppAdjAmt.store(hIppsLikeAmt.value().subtract(hPreDppPay.value()));
                ppsFinalPayAmt.store(hPreDppPay.value().add(ppsLtchDppAdjAmt.value()));
                // TRUNCATES: the expression produces up to 9 integer digits and PPS-FINAL-PAY-AMT holds 7. The high-order digits are lost, as in the original.
            }
        }
    }

